41	     * owner's id. Returns {@code null} when the owner has no id.
42	     */
43	    default String selfLink(Owner owner) {
44	        Integer id = owner.getId();
45	        if (id == null) {
46	            return null;
47	        }
48	        return "/api/owners/" + id;
49	    }
50	
51	    /**
52	     * Derives the owner's age band from the birth date, computed as the owner's age on the
53	     * registration date: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
54	     * {@code SENIOR} at 65 or older. Returns {@code null} when the birth date or registration
55	     * date is absent, so an owner created without a birth date carries no age band.
56	     */
57	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum ageBand(Owner owner) {
58	        java.time.LocalDate birthDate = owner.getBirthDate();
59	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
60	        if (birthDate == null || registrationDate == null) {
61	            return null;
62	        }
63	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
64	        if (age < 18) {
65	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
66	        }
67	        if (age < 65) {
68	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
69	        }
70	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
71	    }
72	
73	    /**
74	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
75	     * in the owner's customer code. Returns {@code null} when the customer code is absent.
76	     */
77	    default Integer checkDigit(Owner owner) {
78	        String customerCode = owner.getCustomerCode();
79	        if (customerCode == null) {
80	            return null;
81	        }
82	        int sum = 0;
83	        boolean dbl = true;
84	        for (int i = customerCode.length() - 1; i >= 0; i--) {
85	            char c = customerCode.charAt(i);
86	            if (c < '0' || c > '9') {
87	                continue;
88	            }
89	            int d = c - '0';
90	            if (dbl) {
91	                d *= 2;
92	                if (d > 9) {
93	                    d -= 9;
94	                }
95	            }
96	            sum += d;
97	            dbl = !dbl;
98	        }
99	        return (10 - (sum % 10)) % 10;
100	    }
101	
102	    /**
103	     * Derives the owner's duplicate-detection identity key: the lower-case SHA-256 hex digest (64 hex
104	     * characters) of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}. The telephone and
105	     * email segments are empty when the respective field is absent, and the last-name segment is the
106	     * {@link #soundex(String) Soundex code} of the owner's last name. The telephone and email are already
107	     * stored in their normalized (E.164 / lower-cased) form, so the stored values are used directly. This
108	     * is the single key against which owner duplicates are detected: two owners collide only when their
109	     * whole keys match.
110	     */
111	    default String identityKey(Owner owner) {
112	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
113	        String email = owner.getEmail() == null ? "" : owner.getEmail();
114	        String lastNameCode = OwnerIdentity.soundex(owner.getLastName());
115	        return OwnerIdentity.sha256Hex(telephone + "|" + email + "|" + lastNameCode);
116	    }
117	
118	    /**
119	     * Fixed city-to-region table used to derive an owner's locality.
120	     */
121	    java.util.Map<String, String> CITY_REGION =
122	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
123	
124	    /**
125	     * Inclusive 4-digit postcode range {@code [low, high]} owned by each region: NSW 2000-2099,
126	     * VIC 3000-3099, QLD 4000-4099. Used to resolve an owner's region from the postcode first.
127	     */
128	    java.util.Map<String, int[]> REGION_POSTCODES =
129	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
130	
131	    /**
132	     * Derives the owner's locality, the {@code REGION} segment of the owner's customer code (the
133	     * region-and-hash identity {@code '<REGION>-<HASH8>'}). Only when no customer code is present does
134	     * it fall back to deriving the region directly, preferring the postcode's {@link #REGION_POSTCODES}
135	     * range and then the fixed {@link #CITY_REGION} city table. Returns the canonical region string, or
136	     * {@code "UNKNOWN"} when neither source resolves a region.
137	     */
138	    default String locality(Owner owner) {
139	        String customerCode = owner.getCustomerCode();
140	        if (customerCode != null) {
141	            int dash = customerCode.indexOf('-');
142	            String region = dash >= 0 ? customerCode.substring(0, dash) : customerCode;
143	            if (!region.isEmpty()) {
144	                return region;
145	            }
146	        }
147	        String postcode = owner.getPostcode();
148	        if (postcode != null) {
149	            try {
150	                int value = Integer.parseInt(postcode.trim());
151	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
152	                    int[] range = entry.getValue();
153	                    if (value >= range[0] && value <= range[1]) {
154	                        return entry.getKey();
155	                    }
156	                }
157	            }
158	            catch (NumberFormatException ex) {
159	                // Not a numeric postcode; fall back to the city table below.
160	            }
161	        }
162	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
163	    }
164	
165	    /**
166	     * Fixed region-to-timezone table used to derive an owner's timezone as an IANA name.
167	     */
168	    java.util.Map<String, String> REGION_TIMEZONE =
169	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
170	
171	    /**
172	     * Derives the owner's timezone as an IANA name from the owner's {@link #locality(Owner) locality}
173	     * (region) via the fixed {@link #REGION_TIMEZONE} table: {@code NSW -> Australia/Sydney},
174	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}. Returns {@code null} when
175	     * the region does not resolve to a known timezone (e.g. the locality is {@code "UNKNOWN"}).
176	     */
177	    default String timezone(Owner owner) {
178	        return REGION_TIMEZONE.get(locality(owner));
179	    }
180	
181	    /**
182	     * Known E.164 country calling codes, longest first, used to split a stored E.164 telephone into
183	     * its country code and national digits when formatting {@link #telephoneDisplay(Owner)}.
184	     */
185	    String[] TELEPHONE_COUNTRY_CODES = {"61", "1"};
186	
187	    /**
188	     * Formats the owner's stored E.164 telephone for humans: the country code, a space, then the
189	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
190	     * The country code is recognised from the {@link #TELEPHONE_COUNTRY_CODES} table; when none matches,
191	     * all digits after the {@code '+'} are treated as the national number. Returns {@code null} when the
192	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164 number.
193	     */
194	    default String telephoneDisplay(Owner owner) {
195	        String telephone = owner.getTelephone();
196	        if (telephone == null) {
197	            return null;
198	        }
199	        if (!telephone.startsWith("+")) {
200	            return telephone;
201	        }
202	        String digits = telephone.substring(1);
203	        if (!digits.chars().allMatch(Character::isDigit)) {
204	            return telephone;
205	        }
206	        String countryCode = "";
207	        for (String code : TELEPHONE_COUNTRY_CODES) {
208	            if (digits.startsWith(code) && digits.length() > code.length()) {
209	                countryCode = code;
210	                break;
211	            }
212	        }
213	        String national = digits.substring(countryCode.length());
214	        StringBuilder grouped = new StringBuilder();
215	        for (int i = 0; i < national.length(); i++) {
216	            if (i > 0 && i % 3 == 0) {
217	                grouped.append(' ');
218	            }
219	            grouped.append(national.charAt(i));
220	        }
221	        return "+" + countryCode + " " + grouped;
222	    }
223	
224	    /**
225	     * Derives the owner's preferred contact channel: {@code "EMAIL"} when an email address is
226	     * present (non-blank), otherwise {@code "PHONE"}.
227	     */
228	    default String contactPreference(Owner owner) {
229	        String email = owner.getEmail();
230	        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
231	    }
232	
233	    /**
234	     * Computes the owner's membership points. Starts at {@code 0} and adds {@code 2} when an email
235	     * is present, {@code 1} when the owner has no namesakes ({@code namesakeCount} is {@code 0}),
236	     * {@code 2} for a household of {@code 3} or more ({@code householdSize}), and {@code 3} when the
237	     * owner's tenure spans at least one elapsed fiscal year (the {@code registrationDate}'s fiscal
238	     * year is earlier than the current date's fiscal year).
239	     */
240	    default Integer membershipPoints(Owner owner) {
241	        Integer namesakeCount = owner.getNamesakeCount();
242	        String email = owner.getEmail();
243	        Integer householdSize = owner.getHouseholdSize();
244	        int points = 0;
245	        if (email != null && !email.isBlank()) {
246	            points += 2;
247	        }
248	        if (namesakeCount != null && namesakeCount == 0) {
249	            points += 1;
250	        }
251	        if (householdSize != null && householdSize >= 3) {
252	            points += 2;
253	        }
254	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
255	        boolean hasTenure = registrationDate != null
256	            && fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate) >= 1;
257	        if (hasTenure) {
258	            points += 3;
259	        }
260	        return points;
261	    }
262	
263	    /**
264	     * Derives the owner's membership level, a number from 1 to 4, from the owner's
265	     * {@link #membershipPoints(Owner) membership points}: level {@code 1} for {@code 0-1} points,
266	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
267	     *
268	     * <p>The derived level is then capped by the owner's {@code membershipLevelCap} when one was
269	     * snapshotted at creation: a new owner's membership level cannot exceed one above the highest
270	     * membership level among their existing household members. When no cap is present (the owner had no
271	     * existing household member) the derived level is returned unchanged.
272	     */
273	    default Integer membershipLevel(Owner owner) {
274	        int points = membershipPoints(owner);
275	        int level;
276	        if (points <= 1) {
277	            level = 1;
278	        } else if (points <= 3) {
279	            level = 2;
280	        } else if (points <= 5) {
281	            level = 3;
282	        } else {
283	            level = 4;
284	        }
285	        Integer cap = owner.getMembershipLevelCap();
286	        if (cap != null && level > cap) {
287	            return cap;
288	        }
289	        return level;
290	    }
291	
292	    /**
293	     * Builds the owner's membership number, formatted {@code '<customerCode>-M<YY>'} where
294	     * {@code YY} is the last two digits of the registration date's fiscal year (e.g.
295	     * {@code "NSW-3F2A1B9C-M26"}). Returns {@code null} when the customer code or registration date
296	     * is absent.
297	     */
298	    default String membershipNumber(Owner owner) {
299	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
300	            return null;
301	        }
302	        int yy = fiscalYearValue(owner.getRegistrationDate()) % 100;
303	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
304	    }
305	
306	    /**
307	     * Derives the owner's fiscal year from the business-day-adjusted registration date, formatted
308	     * {@code 'FY<YY>'} where {@code YY} is the last two digits of the fiscal year (e.g.
309	     * {@code "FY26"}). Returns {@code null} when the registration date is absent.
310	     */
311	    default String fiscalYear(Owner owner) {
312	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
313	        if (registrationDate == null) {
314	            return null;
315	        }
316	        return String.format("FY%02d", fiscalYearValue(registrationDate) % 100);
317	    }
318	
319	    /**
320	     * Computes the fiscal year, as a full four-digit year, of the given date. The fiscal year starts
321	     * on 1 July and is named by the calendar year in which it ends, so a date on or after 1 July
322	     * belongs to the following calendar year's fiscal year.
323	     */
324	    default int fiscalYearValue(java.time.LocalDate date) {
325	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
326	    }
327	
328	    /**
329	     * Builds the owner's salutation: the supplied title and last name joined by a single space
330	     * (e.g. {@code "DR Franklin"}) when a title is present (non-blank), otherwise just the last
331	     * name. Returns {@code null} when the owner has no last name.
332	     */
333	    default String salutation(Owner owner) {
334	        String lastName = owner.getLastName();
335	        String title = owner.getTitle();
336	        if (title == null || title.isBlank()) {
337	            return lastName;
338	        }
339	        return title + " " + lastName;
340	    }
341	
342	    /**
343	     * Builds the owner's initials as the upper-cased first letters of the first and last
344	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
345	     */
346	    default String initials(Owner owner) {
347	        String first = owner.getFirstName();
348	        String last = owner.getLastName();
349	        StringBuilder sb = new StringBuilder();
350	        if (first != null && !first.isEmpty()) {
351	            sb.append(Character.toUpperCase(first.charAt(0))).append('.');
352	        }
353	        if (last != null && !last.isEmpty()) {
354	            sb.append(Character.toUpperCase(last.charAt(0))).append('.');
355	        }
356	        return sb.toString();
357	    }
358	
359	    Owner toOwner(OwnerDto ownerDto);
